try:
    import pycosat
    print("pycosat available")
except:
    print("pycosat not available")

from z3 import *

# Parameters
num_players = 30
num_groups = 10
group_size = 3
num_weeks = 8

# Variables: group[w][p] = group number (0-9) for player p in week w
group = [[Int(f'g_{w}_{p}') for p in range(num_players)] for w in range(num_weeks)]

s = Solver()

# Domain constraints: each player is in a group 0-9
for w in range(num_weeks):
    for p in range(num_players):
        s.add(group[w][p] >= 0, group[w][p] < num_groups)

# Partition constraint: each group has exactly 3 players
# For each week and each group, count players in that group = 3
for w in range(num_weeks):
    for g in range(num_groups):
        s.add(Sum([If(group[w][p] == g, 1, 0) for p in range(num_players)]) == group_size)

# No pair constraint: no two players are in the same group more than once across all weeks
# For each pair of players and each pair of weeks, they can't be in same group in both weeks
for p1 in range(num_players):
    for p2 in range(p1+1, num_players):
        for w1 in range(num_weeks):
            for w2 in range(w1+1, num_weeks):
                s.add(Not(And(group[w1][p1] == group[w1][p2], group[w2][p1] == group[w2][p2])))

print(f"Number of assertions: {len(s.assertions())}")

m = s.model()

# Extract solution
solution = []
for w in range(num_weeks):
    for p in range(num_players):
        val = m.evaluate(group[w][p]).as_long()
        solution.append(val)

print(f"Solution length: {len(solution)}")
print(f"First 30 values (week 0): {solution[:30]}")
print(f"Week 1: {solution[30:60]}")

# Verify the solution
def verify(sol):
    # Check week 0 partition
    for w in range(num_weeks):
        week = sol[w*30:(w+1)*30]
        for g in range(10):
            count = week.count(g)
            if count != 3:
                print(f"Week {w}, group {g} has {count} players, expected 3")
                return False

    # Check no pair appears twice
    pair_count = {}
    for w in range(num_weeks):
        week = sol[w*30:(w+1)*30]
        # Build groups
        groups = [[] for _ in range(10)]
        for p in range(30):
            groups[week[p]].append(p)

        for g in range(10):
            for i in range(3):
                for j in range(i+1, 3):
                    pair = tuple(sorted((groups[g][i], groups[g][j])))
                    if pair in pair_count:
                        print(f"Pair {pair} appears in week {pair_count[pair]} and week {w}")
                        return False
                    pair_count[pair] = w

    print("Solution is valid!")
    return True

verify(solution)
